// IDs persistentes: novos controles não devem reutilizar identificadores removidos.
export const retiredControls = [];
// Cada tupla: ID persistente, pergunta verificável, evidência esperada, bloqueador, rigor mínimo (1 a 3).
function station(id, line, phase, title, summary, owner, approver, artifacts, checks, detail) {
  return { id, line, phase, title, summary, owner, approver, artifacts,
    controls: checks.map(([id, question, evidence, critical = false, tier = 1]) => ({ id, question, evidence, critical, tier })), ...detail };
}
