// Dependências representam pontos de decisão, não um cronograma em cascata.
for (const line of lines) {
  const route = stations.filter(s => s.line === line.id).sort((a, b) => a.phase - b.phase);
  route.forEach((s, i) => { s.dependsOn = i ? [route[i - 1].id] : []; });
}
const dependencies = {
  p2: ['p1', 'c1'], s2: ['p1'], a2: ['p1', 'c1'], d2: ['d1', 'p1'],
  p3: ['p2', 'c2'], s3: ['s2', 'c2'], d3: ['d2', 'c2'], a3: ['a2', 'd2', 'c2'], o3: ['p2'],
  p6: ['p5', 's5', 'd5', 'a5', 'c5', 'o5'],
  a6: ['a5', 'd5', 'c5'], s6: ['s5', 'o5'], d6: ['d5', 'c5'],
  p7: ['p6', 'o6']
};
for (const [id, deps] of Object.entries(dependencies)) stations.find(s => s.id === id).dependsOn = deps;

export const glossary = [
  ['Artefato', 'Registro útil para executar ou decidir: pode ser documento, issue, contrato, teste ou log. Sua qualidade importa mais que o formato.'],
  ['Gate / marco de decisão', 'Ponto de revisão com critérios, responsável e evidências. Pode resultar em continuar, corrigir, reduzir escopo, pausar ou encerrar.'],
  ['Bloqueador', 'Controle crítico que deve ter evidência válida antes do avanço. Um percentual alto não compensa esse impedimento.'],
  ['Data owner / steward', 'Owner decide sobre responsabilidade e uso de um domínio. Steward mantém definições, qualidade e coordenação no dia a dia.'],
  ['CDE', 'Elemento crítico de dados: campo cujo erro compromete decisão, obrigação, segurança ou resultado relevante.'],
  ['RACI', 'Matriz que distingue quem executa, responde pela decisão, é consultado e é informado. Evite decisões sem responsável final.'],
  ['ADR', 'Registro de decisão de arquitetura: contexto, alternativas, escolha, consequências e condições para revisão.'],
  ['RAID', 'Registro integrado de riscos, premissas, problemas e dependências, com dono, resposta e acompanhamento.'],
  ['SLA / SLO / SLI', 'SLA é acordo de serviço; SLO é objetivo de confiabilidade; SLI é o indicador usado para medi-lo.'],
  ['RPO / RTO', 'RPO delimita perda de dados tolerável no tempo. RTO delimita tempo de recuperação tolerável. Ambos precisam ser pactuados com o negócio.'],
  ['Deriva', 'Mudança nos dados ou no comportamento de um sistema de IA que pode degradar seu desempenho ou alterar impacto.'],
  ['Baseline', 'Referência inicial para comparação, como o desempenho atual do processo ou uma solução sem IA.'],
  ['RIPD', 'Relatório de Impacto à Proteção de Dados Pessoais. A necessidade e o conteúdo devem ser avaliados conforme contexto e requisitos aplicáveis.'],
  ['Evidência válida', 'Neste guia: referência verificável, revisor e data não futura; validade não vencida quando informada. O guia não acessa nem audita a referência.']
];
